CREATE OR REPLACE PROCEDURE public.sp_assign_user_branch(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_user_id uuid, IN p_assigned_by uuid DEFAULT NULL::uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_canonical_tenant_id uuid; BEGIN     -- Resolve canonical tenant_id from the organization to guarantee FK integrity     SELECT tenant_id INTO v_canonical_tenant_id FROM organizations WHERE id = p_organization_id;     IF v_canonical_tenant_id IS NULL THEN         v_canonical_tenant_id := p_tenant_id;     END IF;      INSERT INTO user_branch_assignments (user_id, branch_id, organization_id, tenant_id, assigned_by, created_at, revoked_at)     VALUES (p_user_id, p_branch_id, p_organization_id, v_canonical_tenant_id, p_assigned_by, NOW(), NULL)     ON CONFLICT (user_id, branch_id) DO UPDATE     SET revoked_at = NULL,         tenant_id = v_canonical_tenant_id,         organization_id = p_organization_id,         assigned_by = COALESCE(p_assigned_by, user_branch_assignments.assigned_by); END; $procedure$ ;
